import { EventEmitter } from 'events';
import { webcrypto } from 'crypto';

// Explicitly bind to the Web Crypto API to guarantee a CSPRNG is used
// for security-sensitive nonce generation.
const secureCrypto = webcrypto as unknown as Crypto;

interface TokenPayload {
  serviceId: string;
  scopes: string[];
  expiresAt: number;
  nonce: Uint8Array;
}

interface AuthSession {
  token: TokenPayload;
  refreshHandle: NodeJS.Timeout | null;
  revoked: boolean;
}

class TokenPool {
  private sessions: Map<string, AuthSession> = new Map();
  private recycledTokens: TokenPayload[] = [];
  private maxPoolSize: number = 32;

  allocate(serviceId: string, scopes: string[]): TokenPayload {
    // Check recycled pool first for performance
    const recycled = this.recycledTokens.find(
      t => t.serviceId === serviceId && this.scopesMatch(t.scopes, scopes)
    );
    if (recycled) {
      this.recycledTokens = this.recycledTokens.filter(t => t !== recycled);
      recycled.expiresAt = Date.now() + 3600000;
      recycled.nonce = secureCrypto.getRandomValues(new Uint8Array(16));
      return recycled;
    }
    return {
      serviceId,
      scopes: [...scopes],
      expiresAt: Date.now() + 3600000,
      nonce: secureCrypto.getRandomValues(new Uint8Array(16))
    };
  }

  release(token: TokenPayload): void {
    if (this.recycledTokens.length < this.maxPoolSize) {
      this.recycledTokens.push(token);
    }
  }

  private scopesMatch(a: string[], b: string[]): boolean {
    return a.length === b.length && a.every((s, i) => s === b[i]);
  }
}

class CrossServiceAuthenticator extends EventEmitter {
  private pool: TokenPool = new TokenPool();
  private activeSessions: Map<string, AuthSession> = new Map();
  private pendingRevocations: Set<string> = new Set();

  async authenticate(serviceId: string, scopes: string[]): Promise<AuthSession> {
    const token = this.pool.allocate(serviceId, scopes);
    const session: AuthSession = {
      token,
      refreshHandle: null,
      revoked: false
    };

    session.refreshHandle = setInterval(() => {
      this.refreshToken(session);
    }, 300000);

    this.activeSessions.set(serviceId, session);
    this.emit('authenticated', { serviceId, tokenNonce: token.nonce });
    return session;
  }

  async revokeSession(serviceId: string): Promise<void> {
    const session = this.activeSessions.get(serviceId);
    if (!session) return;

    this.pendingRevocations.add(serviceId);
    session.revoked = true;

    if (session.refreshHandle) {
      clearInterval(session.refreshHandle);
      session.refreshHandle = null;
    }

    // Release token back to pool for reuse
    this.pool.release(session.token);
    this.activeSessions.delete(serviceId);
    this.pendingRevocations.delete(serviceId);

    this.emit('revoked', { serviceId });
  }

  private refreshToken(session: AuthSession): void {
    if (session.revoked) return;
    // Refresh extends expiry on the SAME token object reference
    session.token.expiresAt = Date.now() + 3600000;
    session.token.nonce = secureCrypto.getRandomValues(new Uint8Array(16));
  }

  getActiveToken(serviceId: string): TokenPayload | null {
    const session = this.activeSessions.get(serviceId);
    if (!session || session.revoked) return null;
    if (session.token.expiresAt < Date.now()) return null;
    return session.token;
  }
}

class ServiceMesh {
  private auth: CrossServiceAuthenticator;
  private cachedCredentials: Map<string, TokenPayload> = new Map();

  constructor() {
    this.auth = new CrossServiceAuthenticator();
    this.auth.on('authenticated', ({ serviceId, tokenNonce }) => {
      const token = this.auth.getActiveToken(serviceId);
      if (token) {
        this.cachedCredentials.set(serviceId, token);
      }
    });
  }

  async connectService(serviceId: string, scopes: string[]): Promise<void> {
    await this.auth.authenticate(serviceId, scopes);
  }

  async disconnectService(serviceId: string): Promise<void> {
    await this.auth.revokeSession(serviceId);
    // Clean up cached reference to prevent use-after-release
    this.cachedCredentials.delete(serviceId);
  }

  async makeAuthenticatedRequest(serviceId: string, endpoint: string): Promise<any> {
    const cred = this.cachedCredentials.get(serviceId);
    if (!cred) throw new Error('No credentials for service');
    if (cred.expiresAt < Date.now()) throw new Error('Token expired');

    return {
      headers: {
        'Authorization': `Bearer ${Buffer.from(cred.nonce).toString('base64')}`,
        'X-Service-Id': cred.serviceId,
        'X-Scopes': cred.scopes.join(',')
      },
      endpoint
    };
  }
}

export { ServiceMesh, CrossServiceAuthenticator, TokenPool };
